'use client';

import { motion, useReducedMotion } from 'motion/react';
import { useId, useState } from 'react';

import {
  ArchiveIcon,
  ChartLineIcon,
  ChevronDownIcon,
  ChevronsUpDownIcon,
  CircleCheckIcon,
  ClockIcon,
  FoldersIcon,
  InboxIcon,
  LogOutIcon,
  PlusIcon,
  SettingsIcon,
  UserIcon,
  UsersIcon,
  type Icon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/registry/ndeko/ui/dropdown-menu';
import { Kbd } from '@/registry/ndeko/ui/kbd';

import {
  AsideCloseButton,
  AsidePreview,
  AsideTitle,
} from './_parts/aside-frame';
import { travelOf } from './_parts/motion';
import { PEOPLE } from './_parts/people';
import { PersonAvatar } from './_parts/person-avatar';
import { Swap } from './_parts/swap';

type Workspace = { id: string; name: string; plan: string; color: string };

type NavItem = { id: string; label: string; icon: Icon; count?: number };

type Project = {
  id: string;
  name: string;
  color: string;
  openTasks: number;
  isTracked: boolean;
};

const WORKSPACES: Workspace[] = [
  {
    id: 'lattice',
    name: 'Lattice',
    plan: 'Team plan',
    color: 'var(--primary)',
  },
  {
    id: 'northfield',
    name: 'Northfield',
    plan: 'Free plan',
    color: 'var(--info)',
  },
];

const NAV_ITEMS: NavItem[] = [
  { id: 'inbox', label: 'Inbox', icon: InboxIcon, count: 3 },
  { id: 'tasks', label: 'My tasks', icon: CircleCheckIcon },
  { id: 'timesheets', label: 'Timesheets', icon: ClockIcon },
  { id: 'reports', label: 'Reports', icon: ChartLineIcon },
  { id: 'team', label: 'Team', icon: UsersIcon },
];

const PROJECTS: Project[] = [
  {
    id: 'atlas',
    name: 'Atlas redesign',
    color: 'var(--primary)',
    openTasks: 21,
    isTracked: true,
  },
  {
    id: 'billing',
    name: 'Billing API',
    color: 'var(--info)',
    openTasks: 9,
    isTracked: false,
  },
  {
    id: 'mobile',
    name: 'Mobile timer',
    color: 'var(--success)',
    openTasks: 14,
    isTracked: false,
  },
];

const ALL_PROJECTS_COUNT = 12;

const ARCHIVED_COUNT = 3;

const ACCOUNT = PEOPLE[0];

const ROW =
  'relative flex h-8 w-full cursor-pointer items-center gap-2.5 rounded-md px-2 text-left text-[13px] outline-none transition-colors duration-150 hover:bg-foreground/[0.04] focus-visible:ring-[3px] focus-visible:ring-ring/25';

function initialOf(name: string) {
  return name.charAt(0);
}

function isWorkspaceId(value: unknown): value is string {
  return WORKSPACES.some((workspace) => workspace.id === value);
}

function WorkspaceTile({ workspace }: { workspace: Workspace }) {
  const tileStyle = { '--gem': workspace.color } as React.CSSProperties;

  return (
    <span
      style={tileStyle}
      aria-hidden='true'
      className='gem-plate flex size-7 shrink-0 items-center justify-center rounded-md text-xs font-semibold'
    >
      {initialOf(workspace.name)}
    </span>
  );
}

function ActiveIndicator({ layoutId }: { layoutId: string }) {
  const shouldReduceMotion = useReducedMotion();
  const transition = travelOf(shouldReduceMotion);

  return (
    <motion.span
      layoutId={layoutId}
      transition={transition}
      aria-hidden='true'
      className='bg-foreground/[0.07] absolute inset-0 -z-10 rounded-md'
    />
  );
}

function SidebarRow({
  isActive,
  indicatorId,
  onSelect,
  children,
}: {
  isActive: boolean;
  indicatorId: string;
  onSelect: () => void;
  children: React.ReactNode;
}) {
  let current: 'page' | undefined;
  if (isActive) {
    current = 'page';
  }

  return (
    <button
      type='button'
      aria-current={current}
      onClick={onSelect}
      className={cn(ROW, isActive && 'font-medium')}
    >
      {isActive && <ActiveIndicator layoutId={indicatorId} />}
      {children}
    </button>
  );
}

function CountCap({ count, label }: { count: number; label: string }) {
  return (
    <span className='ml-auto flex'>
      <Kbd aria-hidden='true'>{count}</Kbd>
      <span className='sr-only'>{label}</span>
    </span>
  );
}

function WorkspaceSwitcher() {
  const [workspaceId, setWorkspaceId] = useState('lattice');
  const workspace =
    WORKSPACES.find((candidate) => candidate.id === workspaceId) ??
    WORKSPACES[0];

  function changeWorkspace(value: unknown) {
    if (isWorkspaceId(value)) {
      setWorkspaceId(value);
    }
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <button
            type='button'
            className='hover:bg-foreground/[0.04] focus-visible:ring-ring/25 data-popup-open:bg-foreground/[0.05] flex min-w-0 flex-1 cursor-pointer items-center gap-2.5 rounded-lg p-1.5 text-left outline-none focus-visible:ring-[3px]'
          />
        }
      >
        <Swap swapKey={workspace.id}>
          <WorkspaceTile workspace={workspace} />
        </Swap>
        <span className='flex min-w-0 flex-1 flex-col'>
          <span className='truncate text-[13px] leading-tight font-semibold'>
            {workspace.name}
          </span>
          <span className='text-muted-foreground truncate text-xs'>
            {workspace.plan}
          </span>
        </span>
        <ChevronsUpDownIcon className='text-muted-foreground size-3.5 shrink-0' />
      </DropdownMenuTrigger>
      <DropdownMenuContent className='w-56'>
        <DropdownMenuLabel>Workspaces</DropdownMenuLabel>
        <DropdownMenuRadioGroup
          value={workspaceId}
          onValueChange={changeWorkspace}
        >
          {WORKSPACES.map((item) => (
            <DropdownMenuRadioItem key={item.id} value={item.id} closeOnClick>
              <WorkspaceTile workspace={item} />
              {item.name}
            </DropdownMenuRadioItem>
          ))}
        </DropdownMenuRadioGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

function AccountMenu() {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <button
            type='button'
            className='hover:bg-foreground/[0.04] focus-visible:ring-ring/25 data-popup-open:bg-foreground/[0.05] flex w-full cursor-pointer items-center gap-2.5 rounded-lg p-1.5 text-left outline-none focus-visible:ring-[3px]'
          />
        }
      >
        <PersonAvatar person={ACCOUNT} presence={ACCOUNT.presence} />
        <span className='flex min-w-0 flex-1 flex-col'>
          <span className='truncate text-[13px] font-medium'>
            {ACCOUNT.name}
          </span>
          <span className='text-muted-foreground truncate text-xs'>
            {ACCOUNT.email}
          </span>
        </span>
        <ChevronsUpDownIcon className='text-muted-foreground size-3.5 shrink-0' />
      </DropdownMenuTrigger>
      <DropdownMenuContent side='top' className='w-56'>
        <DropdownMenuItem>
          <UserIcon />
          Profile
        </DropdownMenuItem>
        <DropdownMenuItem>
          <SettingsIcon />
          Settings
        </DropdownMenuItem>
        <DropdownMenuSeparator />
        <DropdownMenuItem variant='destructive'>
          <LogOutIcon />
          Log out
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

function WorkspaceSidebar() {
  const [activeId, setActiveId] = useState('tasks');
  const [areProjectsOpen, setAreProjectsOpen] = useState(true);
  const indicatorId = useId();
  const projectsListId = useId();

  function toggleProjects() {
    setAreProjectsOpen((previous) => !previous);
  }

  return (
    <nav aria-label='Workspace' className='flex min-h-full flex-col gap-4 p-3'>
      <AsideTitle className='sr-only'>Navigation</AsideTitle>
      <div className='flex items-center gap-1'>
        <WorkspaceSwitcher />
        <AsideCloseButton label='Close navigation' />
      </div>
      <ul className='isolate flex flex-col gap-px'>
        {NAV_ITEMS.map((item) => {
          const ItemGlyph = item.icon;
          const isActive = activeId === item.id;

          function select() {
            setActiveId(item.id);
          }

          return (
            <li key={item.id}>
              <SidebarRow
                isActive={isActive}
                indicatorId={indicatorId}
                onSelect={select}
              >
                <ItemGlyph className='text-muted-foreground size-4 shrink-0' />
                {item.label}
                {item.count !== undefined && (
                  <CountCap count={item.count} label={`${item.count} unread`} />
                )}
              </SidebarRow>
            </li>
          );
        })}
      </ul>
      <section aria-label='Projects' className='flex flex-col gap-px'>
        <div className='flex items-center gap-0.5'>
          <button
            type='button'
            aria-expanded={areProjectsOpen}
            aria-controls={projectsListId}
            onClick={toggleProjects}
            className='text-muted-foreground hover:text-foreground focus-visible:ring-ring/25 flex h-7 flex-1 cursor-pointer items-center gap-1 rounded-md px-2 text-left text-xs font-medium outline-none focus-visible:ring-[3px]'
          >
            Projects
            <ChevronDownIcon
              className={cn(
                'size-3 transition-transform duration-200 ease-(--ease-out-strong)',
                !areProjectsOpen && '-rotate-90'
              )}
            />
          </button>
          <Button
            variant='ghost'
            size='icon-sm'
            aria-label='Create project'
            className='text-muted-foreground'
          >
            <PlusIcon />
          </Button>
        </div>
        <AnimatedSize>
          {areProjectsOpen && (
            <ul id={projectsListId} className='isolate flex flex-col gap-px'>
              {PROJECTS.map((project) => {
                const isActive = activeId === project.id;
                const tileStyle = {
                  '--gem': project.color,
                } as React.CSSProperties;

                function select() {
                  setActiveId(project.id);
                }

                return (
                  <li key={project.id}>
                    <SidebarRow
                      isActive={isActive}
                      indicatorId={indicatorId}
                      onSelect={select}
                    >
                      <span
                        style={tileStyle}
                        aria-hidden='true'
                        className='gem-plate flex size-4 shrink-0 items-center justify-center rounded-[4px] text-[9px] font-semibold'
                      >
                        {initialOf(project.name)}
                      </span>
                      <span className='min-w-0 flex-1 truncate'>
                        {project.name}
                      </span>
                      {project.isTracked && (
                        <span className='text-primary-ink flex items-center'>
                          <ClockIcon className='size-3.5' strokeWidth={2.25} />
                          <span className='sr-only'>Timer running</span>
                        </span>
                      )}
                      <CountCap
                        count={project.openTasks}
                        label={`${project.openTasks} open tasks`}
                      />
                    </SidebarRow>
                  </li>
                );
              })}
              <li>
                <SidebarRow
                  isActive={activeId === 'all-projects'}
                  indicatorId={indicatorId}
                  onSelect={() => setActiveId('all-projects')}
                >
                  <FoldersIcon className='text-muted-foreground size-4 shrink-0' />
                  All projects
                  <CountCap
                    count={ALL_PROJECTS_COUNT}
                    label={`${ALL_PROJECTS_COUNT} projects`}
                  />
                </SidebarRow>
              </li>
              <li>
                <SidebarRow
                  isActive={activeId === 'archived'}
                  indicatorId={indicatorId}
                  onSelect={() => setActiveId('archived')}
                >
                  <ArchiveIcon className='text-muted-foreground size-4 shrink-0' />
                  Archived
                  <CountCap
                    count={ARCHIVED_COUNT}
                    label={`${ARCHIVED_COUNT} archived projects`}
                  />
                </SidebarRow>
              </li>
            </ul>
          )}
        </AnimatedSize>
      </section>
      <div className='mt-auto pt-6'>
        <AccountMenu />
      </div>
    </nav>
  );
}

export default function Aside06() {
  return (
    <AsidePreview
      triggerLabel='Open navigation'
      side='left'
      className='max-w-72'
    >
      <WorkspaceSidebar />
    </AsidePreview>
  );
}

'use client';

import { createContext, useContext } from 'react';

import { PanelsTopLeftIcon, XIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import {
  Sheet,
  SheetClose,
  SheetContent,
  SheetDescription,
  SheetTitle,
  SheetTrigger,
} from '@/registry/ndeko/ui/sheet';

/** Where an aside's content is drawn: open in the page as a preview, or inside the real sheet. */
export type AsideHost = 'preview' | 'sheet';

const AsideHostContext = createContext<AsideHost>('preview');

export function useAsideHost() {
  return useContext(AsideHostContext);
}

export type AsideSide = 'left' | 'right';

const TITLE = 'text-lg leading-tight font-semibold';

const DESCRIPTION = 'text-muted-foreground text-[13px]';

/** The background of the surface the aside sits on, for parts that must cover what scrolls under them. */
export const ASIDE_SURFACE = 'bg-[var(--aside-surface)]';

type AsideTextProps = { className?: string; children: React.ReactNode };

export function AsideTitle({ className, children }: AsideTextProps) {
  const host = useAsideHost();
  if (host === 'sheet') {
    return <SheetTitle className={className}>{children}</SheetTitle>;
  }
  return <h2 className={cn(TITLE, className)}>{children}</h2>;
}

export function AsideDescription({ className, children }: AsideTextProps) {
  const host = useAsideHost();
  if (host === 'sheet') {
    return (
      <SheetDescription className={className}>{children}</SheetDescription>
    );
  }
  return <p className={cn(DESCRIPTION, className)}>{children}</p>;
}

/** The close button of the sheet's header. The preview has nothing to close, so it draws nothing. */
export function AsideCloseButton({
  label = 'Close panel',
  className,
}: {
  label?: string;
  className?: string;
}) {
  const host = useAsideHost();
  if (host === 'preview') {
    return null;
  }
  return (
    <SheetClose
      render={
        <Button
          variant='ghost'
          size='icon-sm'
          aria-label={label}
          className={cn('text-muted-foreground', className)}
        />
      }
    >
      <XIcon />
    </SheetClose>
  );
}

type AsidePreviewProps = {
  /** The content, drawn twice: open in the page, and inside the sheet the trigger opens. */
  children: React.ReactNode;
  triggerLabel: string;
  side?: AsideSide;
  className?: string;
};

/** Shows an aside open and whole on the page, with a small trigger that slides the same content in as a real sheet. */
export function AsidePreview({
  children,
  triggerLabel,
  side = 'right',
  className,
}: AsidePreviewProps) {
  return (
    <div className='flex w-full flex-col items-center gap-4'>
      <AsideHostContext.Provider value='preview'>
        <div
          className={cn(
            'surface-raised flex w-full max-w-sm flex-col overflow-hidden rounded-2xl text-left [--aside-surface:var(--popover)]',
            className
          )}
        >
          {children}
        </div>
      </AsideHostContext.Provider>
      <Sheet>
        <SheetTrigger render={<Button variant='outline' size='sm' />}>
          <PanelsTopLeftIcon />
          {triggerLabel}
        </SheetTrigger>
        <SheetContent
          side={side}
          showCloseButton={false}
          className={cn('gap-0 p-0 [--aside-surface:var(--card)]', className)}
        >
          <AsideHostContext.Provider value='sheet'>
            {children}
          </AsideHostContext.Provider>
        </SheetContent>
      </Sheet>
    </div>
  );
}

import type { Transition, Variants } from 'motion/react';

export const SWAP_TRANSITION: Transition = {
  duration: 0.15,
  ease: [0.2, 0, 0, 1],
};

const TRAVEL_SPRING: Transition = { type: 'spring', bounce: 0, duration: 0.3 };

const INSTANT: Transition = { duration: 0 };

const ENTER: Transition = { duration: 0.2, ease: [0.23, 1, 0.32, 1] };

const LEAVE: Transition = { duration: 0.14, ease: [0.23, 1, 0.32, 1] };

const ICON_SWAP: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const LABEL_SWAP: Variants = {
  enter: { opacity: 0, filter: 'blur(2px)' },
  visible: { opacity: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, filter: 'blur(2px)' },
};

const FADE: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

const HEIGHT_PRESENCE: Variants = {
  hidden: { height: 0, opacity: 0, overflow: 'hidden', transition: LEAVE },
  shown: {
    height: 'auto',
    opacity: 1,
    transition: ENTER,
    transitionEnd: { overflow: 'visible' },
  },
};

const FADE_PRESENCE: Variants = {
  hidden: { opacity: 0, transition: LEAVE },
  shown: { opacity: 1, transition: ENTER },
};

const CHIP_PRESENCE: Variants = {
  hidden: { opacity: 0, scale: 0.9, transition: LEAVE },
  shown: { opacity: 1, scale: 1, transition: ENTER },
};

export type SwapKind = 'icon' | 'label';

export function swapVariantsOf(
  shouldReduceMotion: boolean | null,
  kind: SwapKind = 'icon'
) {
  if (shouldReduceMotion) {
    return FADE;
  }
  if (kind === 'label') {
    return LABEL_SWAP;
  }
  return ICON_SWAP;
}

/** A row that joins or leaves a list: its height opens or collapses, so what follows slides instead of jumping. */
export function rowVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_PRESENCE;
  }
  return HEIGHT_PRESENCE;
}

export function chipVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_PRESENCE;
  }
  return CHIP_PRESENCE;
}

export function travelOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return TRAVEL_SPRING;
}

